        return PlayRequest.parse(body)!!
    }
    assertEquals(id, request(id).flow3Vietsub)
    assertEquals(null, request(null).flow3Vietsub)
    assertEquals(null, request(true).flow3Vietsub)
    assertEquals(null, request("bad").flow3Vietsub)
